package com.sakib.portebo.service;
import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import com.sakib.portebo.data.AppTierManager;import com.sakib.portebo.lockdown.LockdownManager;
public class BootReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){if(i==null||i.getAction()==null)return;String a=i.getAction();if(Intent.ACTION_BOOT_COMPLETED.equals(a)||"android.intent.action.QUICKBOOT_POWERON".equals(a)){AlarmScheduler.rescheduleDailyAlarms(c);if(LockdownManager.isLockdownActive())AppMonitorService.checkImmediateForegroundLock(c);}else if(Intent.ACTION_PACKAGE_ADDED.equals(a)||Intent.ACTION_PACKAGE_REMOVED.equals(a)){new Thread(()->AppTierManager.reconcileWithInstalledApps(c),"portebo-package-refresh").start();}else if("com.sakib.portebo.DAILY_ROUTINE".equals(a)||"com.sakib.portebo.EXAM_ROUTINE".equals(a)){int m=i.getIntExtra("duration",240);LockdownManager.startLockdown(c,Math.max(1,m),"com.sakib.portebo.EXAM_ROUTINE".equals(a)?LockdownManager.LockdownSource.EXAM_ROUTINE:LockdownManager.LockdownSource.DAILY_ROUTINE);AlarmScheduler.rescheduleDailyAlarms(c);}}}
